export type NextLogoFamilyId = keyof typeof NEXT_LOGO_FAMILIES;

export function nextLogoFamily(id: string): NextLogoFamily {
  return NEXT_LOGO_FAMILIES[id] ?? NEXT_LOGO_FAMILIES["transperfect"]!;
}

/**
 * The lockup to place on a panel: stacked white by default, the side-by-side
 * white lockup once the available area is clearly horizontal.
 */
export function pickNextLogo(
  familyId: string,
  aspect: number,
): { art: NextLogoArt; orientation: "stacked" | "side" } {
  const family = nextLogoFamily(familyId);
  const wantSide = aspect >= 1.6;
  const first = wantSide ? family.side : family.stacked;
  const fallback = wantSide ? family.stacked : family.side;
  const art = first ?? fallback!;
  return { art, orientation: art === family.side ? "side" : "stacked" };
}
